class PayPalProcessor {
  process(amount: number) { /* uses dollars */ }
}
class StripeProcessor {
  charge(cents: number) { /* uses cents */ }
}
function createGateway(type: string) {
  return type === 'paypal' ? new PayPalProcessor() : new StripeProcessor();
}
const g = createGateway('paypal');
if (g instanceof PayPalProcessor) g.process(10);
else (g as StripeProcessor).charge(1000);

// Version A: callers detect provider types and call provider specific methods
class PayPal { process(amount: number) {/*...*/} }
class Stripe { charge(cents: number) {/*...*/} }
function makeGateway(type: string) { return type === 'paypal' ? new PayPal() : new Stripe(); }
const g = makeGateway('paypal');
if (g instanceof PayPal) g.process(10);
else (g as Stripe).charge(1000);

// Version B: adapters implement a shared interface so callers use a single abstraction
interface PaymentGateway { pay(cents: number): void }
class PayPalAdapter implements PaymentGateway { constructor(private p: PayPal){} pay(cents:number){ this.p.process(cents / 100); } }
class StripeAdapter implements PaymentGateway { constructor(private s: Stripe){} pay(cents:number){ this.s.charge(cents); } }
const gateway: PaymentGateway = new PayPalAdapter(new PayPal());
gateway.pay(1000);
